#!/usr/bin/env node

import { readFileSync } from 'node:fs';

const usage = 'Usage: wordfreq [-n <count>] [--ignore-case] [--min-length <k>] <file...>';

try {
  const args = process.argv.slice(2);
  const files = [];
  let count = 10;
  let minLength = 1;
  let ignoreCase = false;
  let positional = false;
  for (let i = 0; i < args.length; i++) {
    const arg = args[i];
    if (positional) files.push(arg);
    else if (arg === '--') positional = true;
    else if (arg === '--help' || arg === '-h') {
      console.log(usage);
      process.exit(0);
    } else if (arg === '--ignore-case') ignoreCase = true;
    else if (arg === '-n' || arg === '--min-length') {
      const value = args[++i];
      if (!/^\d+$/.test(value ?? '') || !Number.isSafeInteger(Number(value))) {
        throw new Error(`${arg} requires a non-negative integer`);
      }
      if (arg === '-n') count = Number(value);
      else minLength = Number(value);
    } else if (arg.startsWith('-')) throw new Error(`Unknown option: ${arg}`);
    else files.push(arg);
  }
  if (!files.length) throw new Error(usage);

  const frequencies = new Map();
  for (const file of files) {
    const text = readFileSync(file, 'utf8').normalize('NFC');
    for (let word of text.match(/\p{L}[\p{L}\p{M}]*/gu) ?? []) {
      if (ignoreCase) word = word.toLowerCase();
      if ([...word].length < minLength) continue;
      frequencies.set(word, (frequencies.get(word) ?? 0) + 1);
    }
  }
  const words = [...frequencies].sort((a, b) => b[1] - a[1] || (a[0] < b[0] ? -1 : a[0] > b[0] ? 1 : 0)).slice(0, count);
  for (const [word, frequency] of words) console.log(`${word}\t${frequency}`);
} catch (error) {
  console.error(`wordfreq: ${error.message}`);
  process.exitCode = 1;
}
EOF
